        @Test
        @DisplayName("bhvOperations095 uploadPetDocument sends non-string scalar parts as plain text parts")
        fun testUploadPetDocumentScalarParts() {
            // F1125/D36: boolean, integer, date-time and enum parts carry their text form and no Content-Type.
            var wire = ""
            val api = capturingPetApi("""{"code":200,"type":"ok","message":"m"}""") { _, body -> wire = body }

            runBlocking {
                api.uploadPetDocument(
                    1L,
                    UploadPetDocumentOptions(
                        _file = "doc".toByteArray(),
                        isPrimary = true,
                        pageCount = 3L,
                        takenAt = java.time.OffsetDateTime.parse("2024-01-15T10:30:00Z"),
                        swatch = Swatch.RED,
                    ),
                )
            }

            val expected =
                mapOf(
                    "isPrimary" to "true",
                    "pageCount" to "3",
                    "takenAt" to "2024-01-15T10:30:00.000+00:00",
                    "swatch" to "red",
                )
            for ((name, text) in expected) {
                val start = wire.indexOf("name=\"$name\"")
