                val part = wire.substring(start, wire.indexOf("\r\n--", start))
                assertFalse(part.contains("Content-Type"), "part $name must carry no Content-Type: $part")
                assertTrue(part.endsWith("\r\n\r\n$text"), "part $name must be $text: $part")
            }
        }

