        @Test
        @DisplayName("bhvOperations068 optional-array-param: array query params serialize as styled values, not a debug blob")
        fun testGetPetTagOptionalArrayQuerySerializesStyled() {
            // optional-array-param parity: getPetTag carries two OPTIONAL array
            // query params -- `colors` (style pipeDelimited) and `sizes` (style
            // spaceDelimited). When supplied with multiple values they must reach
            // the wire as the OAS style-encoded form, NOT a language-debug
            // rendering of the collection (Kotlin's List.toString() -> "[blue,
            // black]", which would percent-encode to %5Bblue%2C+black%5D). Each
            // element is joined by the param's declared separator and then
            // URL-encoded once: colors -> "blue|black" -> colors=blue%7Cblack,
            // sizes -> "S M" -> sizes=S%20M. We capture the outbound query string
            // and assert both the styled form is present and the debug blob is
            // absent.
            var capturedQuery: String? = null
            val engine =
                MockEngine { request ->
                    capturedQuery = request.url.encodedQuery
                    respond(
                        content = """{"id":1,"name":"Rex","photoUrls":[]}""",
                        status = HttpStatusCode.OK,
                        headers = headersOf("Content-Type", "application/json"),
                    )
                }
            val config =
                Configuration
                    .builder()
                    .baseUrl("http://localhost")
                    .build()
            val api = PetApi(DefaultApiClient(HttpClient(engine)), config)

            runBlocking {
                api.getPetTag(
                    5L,
                    "cute",
                    GetPetTagOptions(
                        colors = listOf("blue", "black"),
                        sizes = listOf("S", "M"),
                    ),
                )
            }

            val query = capturedQuery
            assertNotNull(query, "no query string was captured")
            // The styled (separator-joined, then percent-encoded) wire form is
            // present for each array param.
            assertTrue(
                query!!.contains("colors=blue%7Cblack"),
                "colors must serialize as the pipeDelimited styled value, query was: $query",
            )
            assertTrue(
                query.contains("sizes=S%20M"),
                "sizes must serialize as the spaceDelimited styled value, query was: $query",
            )
            // The language-debug rendering of the collection must NOT appear:
            // no bracketed List.toString() blob, raw or percent-encoded, for
            // either param.
            assertFalse(
                query.contains("%5B") || query.contains("%5D") || query.contains("["),
                "array params must not leak a List.toString() debug blob, query was: $query",
            )
            assertFalse(
                query.contains("blue,") || query.contains("blue%2C") || query.contains("blue+black"),
                "colors must not be a comma/space-joined debug blob, query was: $query",
            )
        }

        @Test
        @DisplayName("bhvOperations125 required-nested-param-validation: missing required query param fails loud")
        fun testGetPetByNameMissingRequiredQueryFailsLoud() {
            // required-nested-param-validation: `category` is a REQUIRED query
            // param carried in options. A null value (e.g. arriving via Java
            // interop, which bypasses Kotlin's compile-time null check) must
            // fail loud, never be silently dropped from the request. The
            // generated getPetByName emits a requireNotNull guard mirroring the
            // path/body checks; the non-null Options field is a second barrier.
            // Either way a null required param surfaces a RuntimeException.
            val config =
                Configuration
                    .builder()
                    .baseUrl("http://localhost")
                    .build()
            val api = PetApi(DefaultApiClient(), config)

            // forceNull() launders a null through an erased type parameter so it
            // reaches the required slot the way a null crosses the Java/Kotlin
            // boundary, rather than being rejected at a cast site in the test.
            assertThrows(RuntimeException::class.java) {
                runBlocking {
                    api.getPetByName(
                        "Rex",
                        GetPetByNameOptions(category = forceNull(), xCorrelationId = "corr-1"),
                    )
                }
            }
        }

        @Test
        @DisplayName("bhvOperations049 required-nested-param-validation: empty required string query param fails loud")
        fun testGetPetByNameEmptyRequiredQueryFailsLoud() {
            // required-nested-param-validation: a REQUIRED string param must be
            // rejected when it is the empty string, not just when it is null.
            // This mirrors go/rust/swift/elixir, which treat "" as missing for a
            // required string. The generated guard adds an isNotEmpty() check
            // alongside the requireNotNull, so an empty `category` fails loud.
            val config =
                Configuration
                    .builder()
                    .baseUrl("http://localhost")
                    .build()
            val api = PetApi(DefaultApiClient(), config)

            val ex =
