        @Test
        @DisplayName("bhvOperations069 format:date query, header and form params serialize as YYYY-MM-DD with no time")
        fun testFormatDateParamsAreDateOnly() {
            // Case 14: a date-only (`format: date`) value must reach the wire as
            // YYYY-MM-DD with no time component, in the query string, a header
            // and a urlencoded form field alike.
            var capturedUrl: String? = null
            var capturedHeader: String? = null
            var capturedBody: String? = null
            val engine =
                MockEngine { request ->
                    if (request.method.value == "GET") {
                        capturedUrl = request.url.toString()
                        capturedHeader = request.headers["Report-Date"]
                        respond(
                            content = "[]",
                            status = HttpStatusCode.OK,
                            headers = headersOf("Content-Type", "application/json"),
                        )
                    } else {
                        capturedBody = String(request.body.toByteArray(), Charsets.UTF_8)
                        respond(
                            content = """{"code":200,"type":"ok","message":"saved"}""",
                            status = HttpStatusCode.OK,
                            headers = headersOf("Content-Type", "application/json"),
                        )
                    }
                }
            val config =
                Configuration
                    .builder()
                    .baseUrl("http://localhost")
                    .build()
            val api = PetApi(DefaultApiClient(HttpClient(engine)), config)
            val date = LocalDate.of(2024, 1, 1)

            runBlocking {
                api.findPetsByStatus(
                    FindPetsByStatusOptions(bornAfter = date, reportDate = date),
                )
                api.setPetPreferences(
                    1L,
                    SetPetPreferencesOptions(
                        nickname = "rex",
                        renewalDate = date,
                        reminder = OffsetDateTime.parse("2024-01-15T10:30:00Z"),
                    ),
                )
            }

            assertTrue(
                capturedUrl!!.contains("bornAfter=2024-01-01"),
                "bornAfter query must be date-only, got: $capturedUrl",
            )
            assertFalse(capturedUrl!!.contains("bornAfter=2024-01-01T"), "bornAfter must carry no time")
            assertEquals("2024-01-01", capturedHeader)
            assertTrue(
                capturedBody!!.contains("renewalDate=2024-01-01"),
                "renewalDate form field must be date-only, got: $capturedBody",
            )
            assertFalse(capturedBody!!.contains("renewalDate=2024-01-01T"), "renewalDate must carry no time")
            assertTrue(
                capturedBody!!.contains("reminder=2024-01-15T10%3A30%3A00.000%2B00%3A00"),
                "reminder form field must use the canonical date-time form, got: $capturedBody",
            )
        }

