        @Test
        @DisplayName("bhvOperations062 getPetAvatarThumbnail decodes a base64 string sent as application/json to raw bytes")
        fun testGetPetAvatarThumbnailByteOverJson() {
            // Case 13: a top-level `format: byte` response is a JSON string
            // literal. The SDK must JSON-parse it (dropping the quotes) and then
            // base64-decode the inner string to the original bytes.
            val engine =
                MockEngine { _ ->
                    respond(
                        content = "\"dGVzdC1pbWFnZQ==\"",
                        status = HttpStatusCode.OK,
                        headers = headersOf("Content-Type", "application/json"),
                    )
                }
            val config =
                Configuration
                    .builder()
                    .baseUrl("http://localhost")
                    .build()
            val api = PetApi(DefaultApiClient(HttpClient(engine)), config)

            val result = runBlocking { api.getPetAvatarThumbnail(1L) }

            assertEquals("test-image", String(result, Charsets.UTF_8))
            assertArrayEquals("test-image".toByteArray(Charsets.UTF_8), result)
        }

        @Test
        @DisplayName("deserializing an unknown enum value throws an SDK error")
        fun testUnknownEnumValueThrows() {
            // Parity rule 6: an unknown enum value in a response body must
            // surface a (de)serialization error, never be silently coerced to
            // null or a default. The SDK throws its own
            // SerializationException for a status the StatusEnum doesn't define.
            val engine =
                MockEngine { _ ->
                    respond(
                        content = """{"id":1,"name":"Rex","photoUrls":[],"status":"banana"}""",
                        status = HttpStatusCode.OK,
                        headers = headersOf("Content-Type", "application/json"),
                    )
                }
            val config =
                Configuration
                    .builder()
                    .baseUrl("http://localhost")
                    .build()
            val api = PetApi(DefaultApiClient(HttpClient(engine)), config)

            assertThrows(com.example.petstore.errors.SerializationException::class.java) {
                runBlocking { api.getPetById(1L) }
            }
        }

        @Test
        @DisplayName("bhvOperations029 deletePet cookie param with CR/LF fails closed with the RFC 6265 error")
        fun testDeletePetCookieCrlfFailsClosed() {
            // Parity rule 6: an operation cookie param value (the deletePet
            // api_key cookie) carrying a CR/LF or other control character must
            // fail closed at serialization time with the RFC 6265 error, exactly
            // like the auth-cookie validation path, rather than being
            // interpolated raw into the Cookie header (request-header injection).
            val config =
                Configuration
                    .builder()
                    .baseUrl("http://localhost")
                    .build()
            val api = PetApi(DefaultApiClient(), config)

            val ex =
                assertThrows(IllegalArgumentException::class.java) {
                    runBlocking {
                        api.deletePet(
                            1L,
                            DeletePetOptions(apiKey = "session\r\nInjected: 1"),
                        )
                    }
                }
            assertTrue(
                ex.message!!.contains("RFC 6265"),
                "cookie injection must fail with the RFC 6265 error, got: ${ex.message}",
            )
        }

        @Test
        @DisplayName("bhvOperations030 F840: a cookie value of legal cookie-octets is sent exactly as given")
        fun testLegalCookieValueIsSentRaw() {
